#!/bin/zsh
# Overnight run (test_spec_v5_overnight.md): hourly candles for the 71 indexable
# series, then the three-family hourly suite. Resumable: re-running skips done tickers.
cd "$(dirname "$0")"
echo "start $(date)"
python3 -u pull_candles.py --db kalshi.db --interval 60 --max-db-gb 6 --series KXRT KXAAAGASM KXFED KXAAAGASW KXMIDTERMMOV KXCPIYOY KXVOTEPRIMARY KXCPI KXWTIW KXPAYROLLS KXGDP KXEOWEEK KXALBUMSALES KXU3 KXTNOTEW KXAPRPOTUS KXCPICORE KXTRUMPPHOTO KXALBUMEQUIV KXBRENTW KXHORMUZWEEKLY KXTRUTHSOCIAL KXLAGODAYS KXTSAW KXVOTEGENERAL KXCPICOREYOY KXTORNADO KX538APPROVE KXGOLDW KXHURCAT KXYTVIEWSHIGH KXARTISTSTREAMSY KXNETFLIXTOPVIEWSTV KXRAINNYCM KXTRUMPACT KXEGGS KXSILVERW KXNATGASW KXPUREALBUMS KXNETFLIXTOPVIEWSMOVIE KXJOBLESSCLAIMS KXCOPPERW KXPCECORE KXHMONTHRANGE KXMIDTERMVOTETURN KXGAS KXTRUMPENDORSEMENTS KXSPRLVL KXMC KXMAMDANIEO KXUE KXFRM KXVAXX KXTRUMPVH KXART KXPOKEMON KXADP KX538APPROVEMIN KXCASEW KXTECHLAYOFF KXVOTECOUNTY KXGENERICBALLOTVOTEHUB KX538APPROVEMAX KXMTA KXBOOSTER KXBANKRUPTS KXJOBLESS KXCPIAPPAREL KXAMSAVO KXH100W KXA100W
rc=$?
echo "download exit $rc at $(date)"
if [ $rc -ne 0 ]; then echo "download did not finish cleanly; suite not run"; exit $rc; fi
python3 -u hourly_suite.py --db kalshi.db --out report/
echo "suite exit $? at $(date)"
# Stage 3 (test_spec_v6_sports.md): hourly candles for the sports game/season series.
python3 -u pull_candles.py --db kalshi.db --interval 60 --max-db-gb 6 --series KXNFLGAME KXNFLWINS KXNCAAFGAME KXNCAAFWINS KXNCAAFTOPAPRANK KXNCAAMBGAME KXMARMAD KXNCAAWBGAME KXWMARMAD KXPGAR1LEAD KXPGAR3LEAD KXPGATOUR
echo "sports download exit $? at $(date)"
